//! Actual original mutation policy models, constructors, derives and defaults.
use serde_json::{json,Value as J};
use std::{collections::{BTreeMap,HashSet},io::{self,BufRead},panic::{catch_unwind,AssertUnwindSafe},time::{Duration,UNIX_EPOCH}};
use teaql_core::Value;
use teaql_runtime::*;
#[path="../../../rust_values/src/fixture_value.rs"] mod fixture_value;
fn formatted<T:std::fmt::Debug>(v:&T)->J {json!({"compact":format!("{v:?}"),"pretty":format!("{v:#?}"),"lower_hex":format!("{v:x?}"),"upper_hex":format!("{v:X?}"),"pretty_lower_hex":format!("{v:#x?}"),"pretty_upper_hex":format!("{v:#X?}"),"width_precision":format!("{v:>40.2?}"),"fancy":format!("{v:🧊^+18.3?}"),"zero_pad":format!("{v:+012?}")})}
fn panic_text(e:Box<dyn std::any::Any+Send>)->String {e.downcast_ref::<String>().cloned().or_else(||e.downcast_ref::<&str>().map(|s|s.to_string())).unwrap()}
fn identity(j:&J)->MutationPolicyIdentity {MutationPolicyIdentity::new(j["id"].as_str().unwrap(),j["version"].as_str().unwrap(),j["fingerprint"].as_str().unwrap())}
fn key(j:&J)->EntityKey {let id=fixture_value::value(&j["id"]);EntityKey::new(j["entity"].as_str().unwrap().to_owned(),id)}
fn operation(j:&J)->MutationOperation {MutationOperation{kind:match j["kind"].as_str().unwrap(){"Create"=>MutationOperationKind::Create,"Update"=>MutationOperationKind::Update,"Delete"=>MutationOperationKind::Delete,_=>MutationOperationKind::Recover},entity:key(&j["key"]),original_version:j["version"].as_str().map(|v|v.parse().unwrap()),changed_values:j["values"].as_object().unwrap().iter().map(|(k,v)|(k.clone(),fixture_value::value(v))).collect::<BTreeMap<String,Value>>()}}
fn evaluate(j:J)->J {
 match j["type"].as_str().unwrap() {
  "identity"=>match catch_unwind(AssertUnwindSafe(||identity(&j))) {Err(e)=>json!({"panic":panic_text(e)}),Ok(v)=>{let other=identity(&j["other"]);let mut set=HashSet::new();set.insert(v.clone());set.insert(v.clone());set.insert(other.clone());json!({"debug":formatted(&v),"clone":formatted(&v.clone()),"clone_equal":v==v.clone(),"other_equal":v==other,"order":format!("{:?}",v.cmp(&other)),"set_size":set.len()})}},
  "decision"=>match catch_unwind(AssertUnwindSafe(||if j["deny"]==true {MutationDecision::deny(j["code"].as_str().unwrap(),j["message"].as_str().unwrap(),j["fields"].as_array().unwrap().iter().map(|v|v.as_str().unwrap()))}else{MutationDecision::allow()})){Err(e)=>json!({"panic":panic_text(e)}),Ok(v)=>{let mut other=v.clone();other.message=Some("changed".into());json!({"debug":formatted(&v),"clone":formatted(&v.clone()),"clone_equal":v==v.clone(),"changed_equal":v==other,"allowed":v.is_allowed()})}},
  "approval"=>match catch_unwind(AssertUnwindSafe(||{let sec=j["seconds"].as_str().unwrap().parse::<i64>().unwrap();let nanos=j["nanos"].as_u64().unwrap() as u32;let time=if sec>=0{UNIX_EPOCH+Duration::new(sec as u64,nanos)}else{UNIX_EPOCH-Duration::from_secs(sec.unsigned_abs())+Duration::new(0,nanos)};MutationPolicyApproval::new(identity(&j["policy"]),j["approver"].as_str().unwrap(),time)})){Err(e)=>json!({"panic":panic_text(e)}),Ok(v)=>{let mut other=v.clone();other.approved_by.push('!');json!({"debug":formatted(&v),"clone":formatted(&v.clone()),"clone_equal":v==v.clone(),"changed_equal":v==other})}},
  "models"=>{let operations=j["operations"].as_array().unwrap().iter().map(operation).collect::<Vec<_>>();let plan=MutationPlan{execution_id:j["execution"].as_str().unwrap().into(),request_key:j["request"].as_str().unwrap().into(),root_entity_type:j["root"].as_str().unwrap().into(),audit_reason:j["reason"].as_str().map(str::to_owned),operations};let snapshot=MutationGovernanceSnapshot{execution_id:plan.execution_id.clone(),request_key:plan.request_key.clone(),source:if j["customer"]==true{MutationPolicySource::Customer}else{MutationPolicySource::GeneratedDefault},policy:j["policy"].as_object().map(|_|identity(&j["policy"])),approval_status:match j["approval"].as_str().unwrap(){"Approved"=>MutationPolicyApprovalStatus::Approved,"Missing"=>MutationPolicyApprovalStatus::Missing,_=>MutationPolicyApprovalStatus::NotApplicable},warning_codes:j["warnings"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_owned()).collect(),operations:plan.operations.iter().map(|v|MutationOperationSummary{kind:v.kind,entity:v.entity.clone(),changed_fields:v.changed_values.keys().cloned().collect()}).collect()};let event=MutationGovernanceEvent{snapshot:snapshot.clone(),warning_code:j["warning"].as_str().unwrap().into(),first_occurrence:j["first"].as_bool().unwrap()};let mut changed_plan=plan.clone();changed_plan.execution_id.push('!');let mut changed_snapshot=snapshot.clone();changed_snapshot.warning_codes.push("changed".into());let mut changed_event=event.clone();changed_event.first_occurrence=!changed_event.first_occurrence;json!({"plan":formatted(&plan),"plan_clone":formatted(&plan.clone()),"plan_clone_equal":plan==plan.clone(),"plan_changed_equal":plan==changed_plan,"snapshot":formatted(&snapshot),"snapshot_clone":formatted(&snapshot.clone()),"snapshot_clone_equal":snapshot==snapshot.clone(),"snapshot_changed_equal":snapshot==changed_snapshot,"event":formatted(&event),"event_clone":formatted(&event.clone()),"event_clone_equal":event==event.clone(),"event_changed_equal":event==changed_event})},
  "defaults"=>{let empty=EmptyMutationPolicyRegistry::default();let no=NoMutationPolicyApprovalProvider::default();json!({"empty_registry":empty.resolve("Order.saveGraph").is_none(),"no_approval":no.find_approval(&identity(&j["policy"])).is_none(),"warning":MISSING_MUTATION_POLICY_WARNING,"approval_warning":MISSING_MUTATION_POLICY_APPROVAL_WARNING})},
  _=>panic!("unknown policy model fixture")
 }
}
fn main(){std::panic::set_hook(Box::new(|_|{}));for line in io::stdin().lock().lines(){println!("{}",evaluate(serde_json::from_str(&line.unwrap()).unwrap()));}}
